/**
 * Property and invariant tests for the engine.
 *
 * The worked-example fixtures pin the engine to particular figures. These
 * tests pin it to properties that must hold for every input it accepts: money
 * is neither created nor lost, no balance goes negative, the same input always
 * gives the same output, and every contribution is allocated in full. Inputs
 * are generated by fast-check across the whole range the validator accepts,
 * and every projection goes through `validateProjectionInput` first, so a
 * failure here is an engine bug, not a bad input.
 *
 * When a property fails, fast-check shrinks the input to the smallest case
 * that still fails and prints it, along with the seed to replay the run.
 */

import fc from 'fast-check';
import { describe, expect, it, vi } from 'vitest';
import { CURRENT_RULE_SET } from '@/rules';
import { allocateContribution } from './allocation';
import { NO_CONTRIBUTIONS_YET, contributionForMonth } from './contributions';
import { project } from './project';
import type { AccountAmounts, AccountName, ProjectionInput, ProjectionMonth, ProjectionResult } from './types';
import { INPUT_LIMITS, validateProjectionInput, type ProjectionDraft } from './validate';

const ACCOUNTS: readonly AccountName[] = ['ordinary', 'special', 'medisave', 'retirement'];

const total = (amounts: AccountAmounts) => ACCOUNTS.reduce((sum, account) => sum + amounts[account], 0);

/** Projections from 16 to 65 are about 600 months each, so heavy properties run fewer cases. */
const RUNS = { numRuns: 60 };

// Each property projects dozens of lifetimes; the default 5-second timeout is
// too close for a slower CI machine.
vi.setConfig({ testTimeout: 60_000 });

/* Inputs ------------------------------------------------------------------- */

/** A rate as a fraction, drawn as whole basis points so the input is exact. */
const basisPoints = (min: number, max: number) => fc.integer({ min, max }).map((bp) => bp / 10_000);

/**
 * Drafts across the range the validator accepts. Money is in cents: salaries
 * from just above the graduated-rate threshold to well above the wage ceiling,
 * balances up to $500,000, and properties from $100,000 to $2,000,000.
 */
const draftArbitrary: fc.Arbitrary<ProjectionDraft> = fc
  .record({
    year: fc.integer({ min: 2026, max: 2030 }),
    month: fc.integer({ min: 1, max: 12 }),
    currentAge: fc.integer({ min: INPUT_LIMITS.minimumAge, max: INPUT_LIMITS.maximumAge }),
    monthlySalary: fc.integer({ min: 75_001, max: 2_000_000 }),
    salaryGrowthRate: basisPoints(-500, 1_000),
    salaryRaiseMonth: fc.integer({ min: 1, max: 12 }),
    ordinary: fc.integer({ min: 0, max: 50_000_000 }),
    special: fc.integer({ min: 0, max: 50_000_000 }),
    medisave: fc.integer({ min: 0, max: 10_000_000 }),
    housingPlan: fc.constantFrom('none', 'hdb-loan', 'bank-loan') as fc.Arbitrary<ProjectionDraft['housingPlan']>,
    propertyPrice: fc.integer({ min: 10_000_000, max: 200_000_000 }),
    purchaseAfterYears: fc.integer({ min: 0, max: 15 }),
    downpaymentShareOfPrice: basisPoints(0, 10_000),
    downpaymentShareFromOrdinaryAccount: basisPoints(0, 10_000),
    tenure: fc.integer({ min: 1, max: 35 }),
    bankLoanRate: basisPoints(0, 800),
    ordinaryAccountRetention: fc.option(fc.integer({ min: 0, max: 5_000_000 }), { nil: undefined }),
    instalmentsPaidFrom: fc.constantFrom('ordinary-account', 'cash') as fc.Arbitrary<'ordinary-account' | 'cash'>,
  })
  .map((g): ProjectionDraft => {
    const endAge = Math.max(INPUT_LIMITS.projectionEndAge, g.currentAge);
    const maxTenure = g.housingPlan === 'hdb-loan' ? INPUT_LIMITS.maximumTenureYears['hdb-concessionary'] : INPUT_LIMITS.maximumTenureYears.bank;
    return {
      startMonth: `${g.year}-${String(g.month).padStart(2, '0')}`,
      currentAge: g.currentAge,
      monthlySalary: g.monthlySalary,
      salaryGrowthRate: g.salaryGrowthRate,
      salaryRaiseMonth: g.salaryRaiseMonth,
      balances: { ordinary: g.ordinary, special: g.special, medisave: g.medisave },
      housingPlan: g.housingPlan,
      propertyPrice: g.propertyPrice,
      purchaseAge: Math.min(g.currentAge + g.purchaseAfterYears, endAge),
      downpayment: Math.round(g.propertyPrice * g.downpaymentShareOfPrice),
      downpaymentShareFromOrdinaryAccount: g.downpaymentShareFromOrdinaryAccount,
      loanTenureYears: Math.min(g.tenure, maxTenure),
      bankLoanRate: g.bankLoanRate,
      ordinaryAccountRetention: g.ordinaryAccountRetention,
      instalmentsPaidFrom: g.instalmentsPaidFrom,
    };
  });

/**
 * Valid engine inputs. Drafts are built to pass almost always; the few the
 * validator rejects (a pay cut each year that takes a low salary down to the
 * graduated-rate threshold) are skipped, since the engine is never asked to
 * run them.
 */
const inputArbitrary: fc.Arbitrary<ProjectionInput> = draftArbitrary
  .map((draft) => validateProjectionInput(draft))
  .filter((validated) => validated.ok)
  .map((validated) => {
    if (!validated.ok) throw new Error('unreachable: filtered above');
    return validated.input;
  });

/** Runs a property over every month of a projection. */
function forEveryMonth(check: (month: ProjectionMonth, result: ProjectionResult) => void) {
  fc.assert(
    fc.property(inputArbitrary, (input) => {
      const result = project(input);
      for (const month of result.months) check(month, result);
    }),
    RUNS,
  );
}

/* Conservation ------------------------------------------------------------- */

describe('conservation', () => {
  it('opening + contributions + interest - withdrawals = closing, per account, every month', () => {
    // Money also moves between accounts: the MediSave overflow and the age-55
    // transfers. Each is recorded, so the equation accounts for them too.
    forEveryMonth((month) => {
      for (const account of ACCOUNTS) {
        const overflow =
          account === 'medisave' ? -month.medisaveOverflow.amount : month.medisaveOverflow.to[account];
        const withdrawn = account === 'ordinary' ? (month.housing?.withdrawnFromOrdinaryAccount ?? 0) : 0;
        const expected =
          month.openingBalances[account] +
          month.contribution.allocation[account] +
          month.interest.credited[account] -
          withdrawn +
          overflow +
          month.retirementTransfers[account];
        expect(month.closingBalances[account], `${month.month} ${account}`).toBe(expected);
      }
    });
  });

  it('moves between accounts create and lose nothing', () => {
    forEveryMonth((month) => {
      expect(total(month.retirementTransfers), month.month).toBe(0);
      expect(total(month.medisaveOverflow.to), month.month).toBe(month.medisaveOverflow.amount);
      expect(month.medisaveOverflow.to.medisave).toBe(0);
    });
  });

  it('across all accounts, the change each month is contributions + interest - withdrawals', () => {
    forEveryMonth((month) => {
      const withdrawn = month.housing?.withdrawnFromOrdinaryAccount ?? 0;
      expect(total(month.closingBalances) - total(month.openingBalances), month.month).toBe(
        month.contribution.total + total(month.interest.credited) - withdrawn,
      );
    });
  });

  it('chains each month’s opening balances to the last month’s closing', () => {
    fc.assert(
      fc.property(inputArbitrary, (input) => {
        const { months } = project(input);
        expect(months[0]!.openingBalances).toEqual(input.openingBalances);
        for (let index = 1; index < months.length; index++) {
          expect(months[index]!.openingBalances).toEqual(months[index - 1]!.closingBalances);
        }
      }),
      RUNS,
    );
  });

  it('repays exactly what was borrowed, and accrues on exactly what was withdrawn', () => {
    forEveryMonth((month) => {
      if (month.loan) {
        expect(month.loan.closingBalance).toBe(month.loan.openingBalance + month.loan.drawn - month.loan.principal);
        expect(month.loan.instalment).toBe(month.loan.interest + month.loan.principal);
      }
      if (month.housing) {
        expect(month.housing.refundable).toBe(month.housing.principalUsed + month.housing.accruedInterest);
      }
    });
  });
});

/* No negative balances ----------------------------------------------------- */

describe('no negative balances', () => {
  it('never takes any account below zero, nor leaves a fraction of a cent', () => {
    forEveryMonth((month) => {
      for (const account of ACCOUNTS) {
        expect(month.closingBalances[account], `${month.month} ${account}`).toBeGreaterThanOrEqual(0);
        expect(Number.isInteger(month.closingBalances[account]), `${month.month} ${account}`).toBe(true);
      }
    });
  });

  it('never makes a negative contribution, interest credit, loan or housing figure', () => {
    forEveryMonth((month) => {
      const figures = [
        month.contribution.total,
        month.contribution.employee,
        month.contribution.employer,
        ...ACCOUNTS.map((account) => month.interest.credited[account]),
        ...ACCOUNTS.map((account) => month.interest.baseAccrued[account]),
        month.medisaveOverflow.amount,
        ...(month.loan ? [month.loan.openingBalance, month.loan.closingBalance, month.loan.interest, month.loan.principal] : []),
        ...(month.housing
          ? [
              month.housing.withdrawnFromOrdinaryAccount,
              month.housing.paidInCash,
              month.housing.shortfallToCash,
              month.housing.principalUsed,
              month.housing.accruedInterest,
            ]
          : []),
      ];
      for (const figure of figures) expect(figure, month.month).toBeGreaterThanOrEqual(0);
    });
  });

  it('never withdraws for housing below the retained amount', () => {
    forEveryMonth((month) => {
      if (!month.housing || month.housing.withdrawnFromOrdinaryAccount === 0) return;
      const available = month.openingBalances.ordinary + month.contribution.allocation.ordinary;
      expect(available - month.housing.withdrawnFromOrdinaryAccount, month.month).toBeGreaterThanOrEqual(
        month.housing.ordinaryAccountRetention,
      );
    });
  });
});

/* Determinism -------------------------------------------------------------- */

describe('determinism', () => {
  it('gives identical output for repeated runs of the same input', () => {
    fc.assert(
      fc.property(inputArbitrary, (input) => {
        const first = project(input);
        const second = project(structuredClone(input));
        expect(second).toEqual(first);
        expect(JSON.stringify(second)).toBe(JSON.stringify(first));
      }),
      { numRuns: 30 },
    );
  });

  it('never changes the input it was given', () => {
    fc.assert(
      fc.property(inputArbitrary, (input) => {
        const before = structuredClone(input);
        project(input);
        expect(input).toEqual(before);
      }),
      { numRuns: 30 },
    );
  });
});

/* Allocation --------------------------------------------------------------- */

describe('allocation', () => {
  it('always sums to the total contribution, in every month of every projection', () => {
    forEveryMonth((month) => {
      const { allocation } = month.contribution;
      expect(total(allocation), month.month).toBe(month.contribution.total);
      for (const account of ACCOUNTS) expect(allocation[account]).toBeGreaterThanOrEqual(0);
    });
  });

  it('always sums to the total, for any amount at any age and Retirement Account position', () => {
    const fullRetirementSum = CURRENT_RULE_SET.thresholds.fullRetirementSum * 100;
    fc.assert(
      fc.property(
        fc.integer({ min: 0, max: 3_774_000 }),
        fc.integer({ min: 16 * 12, max: 80 * 12 }),
        fc.integer({ min: 0, max: fullRetirementSum * 2 }),
        (contribution, ageInMonths, retirementBalance) => {
          const allocation = allocateContribution({
            rules: CURRENT_RULE_SET,
            ageInMonths,
            total: contribution,
            retirementBalance,
            fullRetirementSum,
          });
          expect(total(allocation)).toBe(contribution);
          for (const account of ACCOUNTS) expect(allocation[account]).toBeGreaterThanOrEqual(0);
          // The Retirement Account share never takes it past the FRS.
          expect(allocation.retirement).toBeLessThanOrEqual(Math.max(0, fullRetirementSum - retirementBalance));
        },
      ),
      { numRuns: 2_000 },
    );
  });

  it('splits every contribution into employee and employer shares that add up, within the ceilings', () => {
    const ceiling = CURRENT_RULE_SET.wageCeilings.ordinaryWageCeiling * 100;
    fc.assert(
      fc.property(
        fc.integer({ min: 75_001, max: 5_000_000 }),
        fc.integer({ min: 16 * 12, max: 80 * 12 }),
        (ordinaryWage, ageInMonths) => {
          const contribution = contributionForMonth({
            rules: CURRENT_RULE_SET,
            ageInMonths,
            ordinaryWage,
            yearToDate: NO_CONTRIBUTIONS_YET,
          });
          expect(contribution.employee + contribution.employer).toBe(contribution.total);
          expect(contribution.employee).toBeGreaterThanOrEqual(0);
          expect(contribution.employer).toBeGreaterThanOrEqual(0);
          expect(contribution.ordinaryWageSubjectToCpf).toBeLessThanOrEqual(ceiling);
          // Contributions are whole dollars.
          expect(contribution.total % 100).toBe(0);
        },
      ),
      { numRuns: 2_000 },
    );
  });
});

/* Rules that must hold whatever the input --------------------------------- */

describe('rules that hold for every input', () => {
  it('never lets MediSave close a month above the Basic Healthcare Sum', () => {
    forEveryMonth((month) => {
      expect(month.closingBalances.medisave, month.month).toBeLessThanOrEqual(month.medisaveOverflow.basicHealthcareSum);
    });
  });

  it('holds nothing in the Special Account from the 55th birthday month on', () => {
    forEveryMonth((month) => {
      if (month.ageInMonths >= 55 * 12) expect(month.closingBalances.special, month.month).toBe(0);
    });
  });

  it('credits interest in December only', () => {
    forEveryMonth((month) => {
      if (!month.month.endsWith('-12')) expect(total(month.interest.credited), month.month).toBe(0);
    });
  });

  it('never lets the CPF principal used for housing go down', () => {
    fc.assert(
      fc.property(inputArbitrary, (input) => {
        let previous = 0;
        for (const month of project(input).months) {
          if (!month.housing) continue;
          expect(month.housing.principalUsed).toBeGreaterThanOrEqual(previous);
          previous = month.housing.principalUsed;
        }
      }),
      RUNS,
    );
  });

  it('runs every month under a named rule set, listed in the result', () => {
    forEveryMonth((month, result) => {
      expect(result.ruleSetIds).toContain(month.ruleSetId);
    });
  });
});
